from collections import deque
from datetime import datetime, timedelta, time


class SpyBullishCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone("America/New_York")
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity("SPY", Resolution.Minute, extendedMarketHours=False)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .CallsOnly()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.current_bucket_end = None
        self.current_bucket_bars = {}

        self.option_symbol = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_price = None
        self.expiration_block_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        # Prevent replacement entries on the expiration date or afterward.
        if self.expiration_block_date is not None and current_date >= self.expiration_block_date:
            if self.option_symbol is not None and self.Portfolio[self.option_symbol].Invested:
                self.Liquidate(
                    self.option_symbol,
                    tag="Expiration protection exit"
                )

        # Immediately liquidate unexpected SPY equity resulting from exercise/assignment.
        if (
            self.spy_symbol in self.Portfolio
            and self.Portfolio[self.spy_symbol].Quantity != 0
        ):
            self.Debug("Unexpected SPY exercise/assignment position; liquidating.")
            self.Liquidate(self.spy_symbol, tag="Unexpected exercise/assignment")
            self.expiration_block_date = current_date

        self._evaluate_minute_exit(slice)

        if self.spy_symbol not in slice.Bars:
            return

        bar = slice.Bars[self.spy_symbol]
        if bar.EndTime.tzinfo is None:
            bar_end = self.Time
        else:
            bar_end = bar.EndTime.astimezone(self.Time.tzinfo)

        if bar_end.time() < time(9, 31) or bar_end.time() > time(16, 0):
            return

        bucket_end = self._bucket_end(bar_end)

        if self.current_bucket_end is None:
            self.current_bucket_end = bucket_end
        elif bucket_end != self.current_bucket_end:
            self._complete_bucket_if_valid(slice)
            self.current_bucket_bars = {}
            self.current_bucket_end = bucket_end

        self.current_bucket_bars[bar_end.replace(second=0, microsecond=0)] = bar

        if bar_end.time() == self.current_bucket_end.time():
            self._complete_bucket_if_valid(slice)
            self.current_bucket_bars = {}
            self.current_bucket_end = None

    def _bucket_end(self, end_time: datetime) -> datetime:
        session_start = end_time.replace(hour=9, minute=30, second=0, microsecond=0)
        minutes_from_start = int((end_time - session_start).total_seconds() // 60)
        bucket_number = (minutes_from_start + 4) // 5
        return session_start + timedelta(minutes=bucket_number * 5)

    def _complete_bucket_if_valid(self, slice: Slice):
        if self.current_bucket_end is None:
            return

        expected = [
            self.current_bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        if any(t not in self.current_bucket_bars for t in expected):
            return

        bars = [self.current_bucket_bars[t] for t in expected]
        close = bars[-1].Close

        self.fast_closes.append(close)
        self.slow_closes.append(close)

        if len(self.fast_closes) < 5 or len(self.slow_closes) < 20:
            self.previous_fast = sum(self.fast_closes) / len(self.fast_closes)
            self.previous_slow = sum(self.slow_closes) / len(self.slow_closes)
            return

        fast = sum(self.fast_closes) / 5.0
        slow = sum(self.slow_closes) / 20.0

        crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        bar_end_time = self.current_bucket_end.time()
        eligible_time = time(9, 45) <= bar_end_time <= time(14, 30)

        self.previous_fast = fast
        self.previous_slow = slow

        if crossover and eligible_time:
            self._try_enter(slice)

    def _try_enter(self, slice: Slice):
        if self.entry_ticket is not None:
            if self.entry_ticket.Status in (
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
        ):
                return

        if self.option_symbol is not None and self.Portfolio[self.option_symbol].Invested:
            return

        if self.expiration_block_date == self.Time.date():
            return

        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        current_date = self.Time.date()
        minimum_expiration = current_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiration
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least 7 calendar days away.")
            return

        selected_expiration = expirations[0]
        minimum_strike = 1.01 * self.Securities[self.spy_symbol].Price

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiration
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        self.option_symbol = selected.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(
            self.option_symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.Debug(
            "Submitted entry for {} expiring {} at strike {}.".format(
                self.option_symbol,
                selected_expiration,
                selected.Strike
            )
        )

    def _evaluate_minute_exit(self, slice: Slice):
        if self.option_symbol is None:
            return

        holding = self.Portfolio[self.option_symbol]
        if not holding.Invested:
            return

        if self.expiration_block_date is not None and self.Time.date() >= self.expiration_block_date:
            return

        security = self.Securities[self.option_symbol]
        expiry_date = security.Symbol.ID.Date.date()

        if self.Time.date() == expiry_date - timedelta(days=1):
            if self.Time.time() >= time(15, 45):
                self._submit_exit("Expiration-eve time stop")
                return

        quote = slice.QuoteBars.get(self.option_symbol)
        if quote is None or self.entry_price is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, tag: str):
        if self.exit_ticket is not None and self.exit_ticket.Status in (
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        ):
            return

        if self.option_symbol is None:
            return

        quantity = self.Portfolio[self.option_symbol].Quantity
        if quantity == 0:
            return

        if self.entry_ticket is not None and self.entry_ticket.Status in (
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        ):
            return

        for order in self.Transactions.GetOpenOrders(self.option_symbol):
            self.Transactions.CancelOrder(order.Id)

        self.exit_ticket = self.MarketOrder(
            self.option_symbol,
            -quantity,
            tag=tag
        )
        self.Debug("Submitted exit: {}.".format(tag))

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = order_event.FillPrice
                expiry = self.Securities[self.option_symbol].Symbol.ID.Date.date()
                self.expiration_block_date = expiry
                self.Debug(
                    "Entry filled for {} at {}.".format(
                        self.option_symbol,
                        self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_,
            ):
                self.entry_ticket = None
                self.option_symbol = None
                self.entry_price = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exit filled for {} at {}.".format(
                        self.option_symbol,
                        order_event.FillPrice
                    )
                )
                self.option_symbol = None
                self.entry_ticket = None
                self.exit_ticket = None
                self.entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self.exit_ticket = None
