                                      .Strikes(-100, 100)
                                      .Expiration(timedelta(0), timedelta(days=365))
        )
        self.option_symbol = self.option.Symbol

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)

        self.bucket_bars = []
        self.bucket_date = None
        self.bucket_end_minute = None
        self.pending_crossover = False

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None
        self.exit_ticket = None
        self.expiration_date = None
        self.block_entries_today = False

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        if self.block_entries_today is False:
            self.block_entries_today = False

        self._handle_unexpected_exercise_or_assignment()

        if self.entry_symbol is not None:
            if current_date >= self.expiration_date:
                self._liquidate_option("expiration processing")
                return

            if self._is_time_stop_due():
                self._liquidate_option("pre-expiration time stop")
            else:
                self._check_profit_target(slice)

        spy_bar = slice.Bars.get(self.spy_symbol)
        if spy_bar is not None:
            self._process_spy_minute(spy_bar)

        if (
            self.pending_crossover
            and self.entry_symbol is None
            and self.entry_ticket is None
            and not self.block_entries_today
        ):
            self.pending_crossover = False
            self._try_enter(slice)

    def _process_spy_minute(self, bar: TradeBar):
        local_end = Extensions.ConvertToEasternTime(self.Time, self.TimeZone)
        bar_end = Extensions.ConvertToEasternTime(bar.EndTime, self.TimeZone)

        if bar_end.date() != local_end.date():
            return

        if bar_end.time() < TimeSpan.FromHours(9.5).ToPythonTime():
            return

        if bar_end.time() > TimeSpan.FromHours(16).ToPythonTime():
            return

        minute = bar_end.minute
        bucket_end_minute = ((minute + 4) // 5) * 5

        if bucket_end_minute > 60:
            return

        if (
            self.bucket_date != bar_end.date()
            or self.bucket_end_minute != bucket_end_minute
        ):
            self.bucket_bars = []
            self.bucket_date = bar_end.date()
            self.bucket_end_minute = bucket_end_minute

        if self.bucket_bars:
            previous = self.bucket_bars[-1]
            if bar.EndTime - previous.EndTime != timedelta(minutes=1):
                self.bucket_bars = []

        self.bucket_bars.append(bar)

        if minute != bucket_end_minute or len(self.bucket_bars) != 5:
            return

        close = self.bucket_bars[-1].Close
        self.bucket_bars = []

        previous_fast = (
            sum(self.fast_closes) / len(self.fast_closes)
            if len(self.fast_closes) == 5 else None
        )
        previous_slow = (
            sum(self.slow_closes) / len(self.slow_closes)
            if len(self.slow_closes) == 20 else None
        )

        self.fast_closes.append(close)
        self.slow_closes.append(close)

        if previous_fast is None or previous_slow is None:
            return

        current_fast = sum(self.fast_closes) / 5
        current_slow = sum(self.slow_closes) / 20

        end_time = bar.EndTime
        if end_time.tzinfo is None:
            end_time = self.TimeZone.ConvertFromUtc(end_time)

        eligible = (
            end_time.time() >= TimeSpan.FromHours(9.75).ToPythonTime()
            and end_time.time() <= TimeSpan.FromHours(14.5).ToPythonTime()
        )

        if eligible and previous_fast <= previous_slow and current_fast > current_slow:
            self.pending_crossover = True

